/**
 * Covers both modes generated by our PHP `table()` function:
 *
 *   1) Client-side  -> <table data-table>            (data is already in the HTML)
 *   2) Async/server -> <table data-table-async data-crud-id="...">
 *      (tbody starts empty, data is fetched from the `get-crud-list` REST route)
 *
 * ...plus a third source for the async mode, generated by
 * custom_listing_table() in the 'listings' feature:
 *
 *   3) Custom listing -> <table data-table-async data-listing-type="..." data-listing-key="...">
 *      (dynamically loaded from feature/{name}, plugin/{name}, or
 *      this-system's custom-listings/ folder — not built via the CRUD
 *      builder — fetched from the sibling `get-custom-listing` REST route)
 *
 * CSS: don't `import "gridjs/dist/theme/mermaid.css"` here — it silently
 * no-ops unless the bundler has a CSS loader wired up for node_modules.
 * Load it as a real <link rel="stylesheet"> in the page head instead (or
 * @import it from your SCSS entry point), which works regardless of
 * bundler config.
 * ============================================================================
 */

import { Grid, html } from 'gridjs';
import { ptBR } from 'gridjs/l10n';
import Sortable from 'sortablejs';

const REST_API_BASE = `${BASE_URL}/${REST_API_BASE_ROUTE}`;
const REST_API_LIST_URL = `${REST_API_BASE}/get-crud-list`;
const REST_API_CUSTOM_LISTING_URL = `${REST_API_BASE}/get-custom-listing`;

const PAGE_LENGTH_OPTIONS = [10, 25, 50, 100];
const DEFAULT_PAGE_LIMIT = PAGE_LENGTH_OPTIONS[0];

const URL_PAGE_PARAM = 'table-page';
const URL_SEARCH_PARAM = 'table-search';

/** Serializes nested data into FormData with bracket notation. */
function appendFormData(fd, data, parentKey) {
  if (Array.isArray(data)) {
    data.forEach((item, i) => {
      appendFormData(fd, item, parentKey ? `${parentKey}[${i}]` : String(i));
    });
  } else if (data !== null && typeof data === 'object') {
    for (const k in data) {
      if (!Object.prototype.hasOwnProperty.call(data, k)) continue;
      appendFormData(fd, data[k], parentKey ? `${parentKey}[${k}]` : k);
    }
  } else if (parentKey) {
    fd.append(parentKey, data == null ? '' : data);
  }
}

/** Fallback id extraction: scrapes `id=123` from an actions cell's HTML. Superseded by findIdColumnIndex(). */
function extractRecordId(actionsHtml) {
  const match = /[?&]id=(\d+)/.exec(actionsHtml || '');
  return match ? match[1] : null;
}

/** Reads `?table-page=` from the URL, defaulting to 1. */
function getUrlPage() {
  const raw = parseInt(new URLSearchParams(window.location.search).get(URL_PAGE_PARAM), 10);
  return Number.isFinite(raw) && raw > 0 ? raw : 1;
}

/** Updates `?table-page=` without a reload or new history entry. */
function syncUrlPage(page) {
  const url = new URL(window.location.href);
  url.searchParams.set(URL_PAGE_PARAM, String(page));
  window.history.replaceState(window.history.state, '', url);
}

/** Reads `?table-search=` from the URL, defaulting to ''. */
function getUrlSearch() {
  return new URLSearchParams(window.location.search).get(URL_SEARCH_PARAM) || '';
}

/** Updates `?table-search=`, removing the param entirely when empty. */
function syncUrlSearch(term) {
  const url = new URL(window.location.href);
  if (term) url.searchParams.set(URL_SEARCH_PARAM, term);
  else url.searchParams.delete(URL_SEARCH_PARAM);
  window.history.replaceState(window.history.state, '', url);
}

/** Finds the head column whose label starts/ends with "id" (first match wins). Used to recover row ids generically. */
function findIdColumnIndex(head) {
  for (let i = 0; i < head.length; i++) {
    const normalized = String(head[i] || '')
      .trim()
      .toLowerCase()
      .replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');
    if (normalized.startsWith('id') || normalized.endsWith('id')) return i;
  }
  return -1;
}

/** Sets `data-row-id` on every <tr>, read from the id column (+ handle-column offset when orderable). */
function applyRowIds(wrapper, idColumnIndex, columnOffset) {
  if (idColumnIndex < 0) return;
  const cellIndex = idColumnIndex + columnOffset;

  wrapper.querySelectorAll('tbody tr').forEach((tr) => {
    const cell = tr.children[cellIndex];
    if (cell) tr.setAttribute('data-row-id', cell.textContent.trim());
  });
}

/** Keeps applyRowIds() applied across re-renders. Getters, since idColumnIndex isn't known until the first response. */
function watchAndApplyRowIds(wrapper, getIdColumnIndex, getColumnOffset) {
  const apply = () => applyRowIds(wrapper, getIdColumnIndex(), getColumnOffset());
  const observer = new MutationObserver(apply);
  observer.observe(wrapper, { childList: true, subtree: true });
  apply();
}

/** Shows/hides the loader div. Showing only removes the `display:none` override, never forces `block`. */
function setLoaderVisible(loader, visible) {
  if (!loader) return;
  if (visible) loader.style.removeProperty('display');
  else loader.style.display = 'none';
}

/**
 * Shows a "Carregando..." overlay ON TOP of `.gridjs-wrapper`, instead of
 * touching its content. Grid.js/Preact owns the table's DOM internally;
 * directly overwriting e.g. `tbody.innerHTML` (an earlier version of this)
 * desyncs Preact's own record of what's there, and when the real data
 * arrives Preact's reconciliation against that stale record can misfire —
 * this was the actual cause of the search box losing focus, not something
 * specific to focus handling. Appending a sibling overlay never touches
 * Preact's own nodes, so its reconciliation stays undisturbed.
 */
function showSearchLoadingOverlay(wrapper) {
  const target = wrapper.querySelector('.gridjs-wrapper');
  if (!target) return;
  if (target.querySelector(':scope > .gridjs-search-loading-overlay')) return;

  if (!target.style.position) target.style.position = 'relative';

  const overlay = document.createElement('div');
  overlay.className = 'gridjs-search-loading-overlay';
  overlay.textContent = 'Carregando...';
  overlay.style.cssText =
    'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,0.7);z-index:1;';
  target.appendChild(overlay);
}

function hideSearchLoadingOverlay(wrapper) {
  const overlay = wrapper.querySelector('.gridjs-search-loading-overlay');
  if (overlay) overlay.remove();
}

/** Keeps `.gridjs-container` hidden while loading, applied the instant it's created (not just after data arrives). */
function watchAndSyncContainerVisibility(wrapper, getIsLoading) {
  const sync = () => {
    const container = wrapper.querySelector('.gridjs-container');
    if (!container) return;
    if (getIsLoading()) container.style.display = 'none';
    else container.style.removeProperty('display');
  };
  const observer = new MutationObserver(sync);
  observer.observe(wrapper, { childList: true, subtree: true });
  sync();
}

/**
 * Restructures Grid.js's pagination into real Bootstrap 5 markup. Final
 * shape: `.gridjs-footer > .gridjs-summary` (flattened out of Grid.js's
 * own `.gridjs-pagination` wrapper) and, separately,
 * `.gridjs-pages > .gridjs-pagination > ul.pagination.pagination-sm > li.page-item > button.page-link`.
 * (Grid.js's own `.gridjs-pagination` around summary+pages is removed;
 * the `.gridjs-pagination` in the final shape is one we build ourselves,
 * nested one level deeper, around just the `<ul>`.)
 *
 * Fully unwraps and rebuilds every call instead of skipping a previous
 * pass — Grid.js/Preact tracks these buttons as direct children of
 * `.gridjs-pages` and can remove/replace them as page count changes; a
 * persisted wrapper gets orphaned (empty) when that happens. Rebuilding
 * fresh avoids that entirely.
 */
function bootstrapifyPagination(wrapper) {
  const footer = wrapper.querySelector('.gridjs-footer');
  if (!footer) return;

  const paginationWrapper = footer.querySelector(':scope > .gridjs-pagination');
  if (paginationWrapper) {
    while (paginationWrapper.firstChild) {
      footer.insertBefore(paginationWrapper.firstChild, paginationWrapper);
    }
    paginationWrapper.remove();
  }

  const pagesContainer = footer.querySelector('.gridjs-pages');
  if (!pagesContainer) return;

  pagesContainer.classList.remove('pagination', 'pagination-sm');
  pagesContainer.classList.add('mb-0');

  // Undo previous wrapping — move buttons back to being direct children of
  // .gridjs-pages, then drop the div/ul wrapper.
  const existingWrapper = pagesContainer.querySelector(':scope > div.gridjs-pagination');
  if (existingWrapper) {
    existingWrapper.querySelectorAll('li.page-item > button').forEach((button) => {
      pagesContainer.insertBefore(button, existingWrapper);
    });
    existingWrapper.remove();
  }

  // Rebuild fresh:
  // <div class="gridjs-pagination"><ul class="pagination pagination-sm"><li class="page-item"><button>.
  const buttons = Array.from(pagesContainer.children).filter((el) => el.tagName === 'BUTTON');
  if (buttons.length === 0) return;

  const paginationDiv = document.createElement('div');
  paginationDiv.className = 'gridjs-pagination';

  const list = document.createElement('ul');
  list.className = 'pagination pagination-sm';

  buttons.forEach((button) => {
    const li = document.createElement('li');
    li.className = 'page-item';
    li.appendChild(button);
    list.appendChild(li);

    button.classList.add('page-link');
    li.classList.toggle('disabled', button.disabled);
    li.classList.toggle('active', button.classList.contains('gridjs-currentPage'));
  });

  paginationDiv.appendChild(list);
  pagesContainer.appendChild(paginationDiv);
}

/**
 * Overwrites Grid.js's pagination summary/current-page button using our
 * own tracked page/limit/total. Needed because `pagination.page` doesn't
 * actually drive Grid.js's internal current-page state when
 * `pagination.server` is configured (confirmed by testing) — only shows up
 * on a forced first-page load (e.g. `?table-page=3`), not real navigation.
 */
function correctPaginationState(wrapper, page, limit, total) {
  const currentPage = page + 1;
  const totalPages = Math.max(1, Math.ceil(total / limit));

  const summary = wrapper.querySelector('.gridjs-summary');
  if (summary) {
    const from = total === 0 ? 0 : page * limit + 1;
    const to = Math.min(total, currentPage * limit);
    summary.title = `Página ${currentPage} de ${totalPages}`;
    summary.innerHTML = `Mostrando <b>${from}</b> até <b>${to}</b> de <b>${total}</b> resultados`;
  }

  const pagesContainer = wrapper.querySelector('.gridjs-pages');
  if (pagesContainer) {
    Array.from(pagesContainer.querySelectorAll('button')).forEach((button) => {
      const isPageNumberButton = /^\d+$/.test(button.textContent.trim());
      if (!isPageNumberButton) return;

      const isCurrent = button.textContent.trim() === String(currentPage);
      button.classList.toggle('gridjs-currentPage', isCurrent);

      const li = button.closest('li');
      if (li) li.classList.toggle('active', isCurrent);
    });
  }
}

/** Keeps bootstrapifyPagination() applied, plus correctPaginationState() when getPaginationState is given (async table only). */
function watchAndBootstrapifyPagination(wrapper, getPaginationState = null) {
  const applyFixes = () => {
    bootstrapifyPagination(wrapper);
    if (getPaginationState) {
      const { page, limit, total } = getPaginationState();
      correctPaginationState(wrapper, page, limit, total);
    }
  };

  // Disconnect before writing — applyFixes() mutates DOM, which would
  // otherwise re-trigger this same observer forever.
  const observer = new MutationObserver(() => {
    observer.disconnect();
    applyFixes();
    observer.observe(wrapper, { childList: true, subtree: true });
  });
  observer.observe(wrapper, { childList: true, subtree: true });
  applyFixes();
}

/** Builds the shared `.gridjs-header` container (length selector + search). Pair with attachGridHeader(). */
function createGridHeader() {
  const header = document.createElement('div');
  header.className = 'gridjs-header';
  return header;
}

/** Keeps `header` as the first child of `.gridjs-container` across re-renders. No-op once already placed. */
function attachGridHeader(wrapper, header) {
  const ensure = () => {
    const container = wrapper.querySelector('.gridjs-container');
    if (!container) return;
    if (container.firstChild !== header) {
      container.insertBefore(header, container.firstChild);
    }
  };
  const observer = new MutationObserver(ensure);
  observer.observe(wrapper, { childList: true, subtree: true });
  ensure();
}

/**
 * Wraps `.gridjs-th-content` + `button.gridjs-sort` in a `<div>` inside
 * each sortable `<th>`. Idempotent (skips a `<th>` already wrapped), which
 * is what keeps this safe to re-run on every mutation without a
 * disconnect/reconnect guard — once wrapped, re-checking causes no further
 * DOM change.
 */
function wrapThSortContent(wrapper) {
  wrapper.querySelectorAll('th.gridjs-th-sort').forEach((th) => {
    if (th.querySelector(':scope > div.gridjs-th-wrap')) return;

    const content = th.querySelector(':scope > .gridjs-th-content');
    if (!content) return;
    const sortButton = th.querySelector(':scope > button.gridjs-sort');

    const div = document.createElement('div');
    div.className = 'gridjs-th-wrap';
    th.insertBefore(div, content);
    div.appendChild(content);
    if (sortButton) div.appendChild(sortButton);
  });
}

/** Keeps wrapThSortContent() applied across re-renders. */
function watchAndWrapThSortContent(wrapper) {
  const observer = new MutationObserver(() => wrapThSortContent(wrapper));
  observer.observe(wrapper, { childList: true, subtree: true });
  wrapThSortContent(wrapper);
}

/**
 * Moves `<table class="gridjs-table">` into a new `<div class="gridjs-table-wrapper">`
 * inside `.gridjs-wrapper`. A move (not a rebuild), so Preact's own
 * reference to the table node stays valid for its future updates.
 * Idempotent: once wrapped, the table is no longer a direct child of
 * `.gridjs-wrapper`, so the lookup below naturally finds nothing on later
 * calls — no explicit "already wrapped" flag needed.
 */
function wrapTableElement(wrapper) {
  const gridjsWrapper = wrapper.querySelector('.gridjs-wrapper');
  if (!gridjsWrapper) return;

  const table = gridjsWrapper.querySelector(':scope > table.gridjs-table');
  if (!table) return;

  const tableWrapper = document.createElement('div');
  tableWrapper.className = 'gridjs-table-wrapper';
  gridjsWrapper.insertBefore(tableWrapper, table);
  tableWrapper.appendChild(table);
}

/** Keeps wrapTableElement() applied across re-renders. */
function watchAndWrapTableElement(wrapper) {
  const observer = new MutationObserver(() => wrapTableElement(wrapper));
  observer.observe(wrapper, { childList: true, subtree: true });
  wrapTableElement(wrapper);
}

/** Creates the "records per page" <select>, appended into `parent`. */
function createLengthSelector(parent, initialLimit, onChange) {
  const container = document.createElement('div');
  container.className = 'gridjs-length-selector';

  const label = document.createElement('label');
  label.textContent = 'Mostrar ';

  const select = document.createElement('select');
  select.className = 'form-select form-select-sm';
  select.style.display = 'inline-block';
  select.style.width = 'auto';
  PAGE_LENGTH_OPTIONS.forEach((limit) => {
    const option = document.createElement('option');
    option.value = String(limit);
    option.textContent = String(limit);
    if (limit === initialLimit) option.selected = true;
    select.appendChild(option);
  });

  select.addEventListener('change', () => {
    onChange(parseInt(select.value, 10));
  });

  label.appendChild(select);
  label.appendChild(document.createTextNode(' registros'));
  container.appendChild(label);

  parent.appendChild(container);
  return select;
}

/**
 * Creates a self-debounced search <input>, appended into `parent`.
 * Not using Grid.js's built-in search: its internal debounce has known
 * bugs with stale values on fast typing/clearing (grid-js/gridjs#1081,
 * #1314, #1413). Reading `input.value` fresh at fire time avoids that.
 */
function createSearchInput(parent, onChange, initialValue = '', debounceMs = 300) {
  const container = document.createElement('div');
  container.className = 'gridjs-search';

  const input = document.createElement('input');
  input.type = 'search';
  input.className = 'form-control form-control-sm gridjs-search-input';
  input.placeholder = 'Pesquisar...';
  input.value = initialValue;

  let debounceTimer = null;
  input.addEventListener('input', () => {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
      onChange(input.value.trim());
    }, debounceMs);
  });

  container.appendChild(input);
  parent.appendChild(container);
  return input;
}

/**
 * Persists the new row order. `endpoint` defaults to `order-record`, or a
 * listing's own custom route via `data-order-endpoint`. `extraFields` is
 * whatever identifying info that endpoint needs (crud_id, or
 * listing_type/listing_key for a custom listing).
 * Suggested contract: POST with `order[0]`, `order[1]`, ... = ids in their
 * new order; handler writes sequential `order_reg` values.
 */
function persistReorder(endpoint, orderedIds, extraFields = {}) {
  const url = `${REST_API_BASE}/${endpoint}`;
  const body = new FormData();
  Object.entries(extraFields).forEach(([key, value]) => body.append(key, value));
  orderedIds.forEach((id, index) => body.append(`order[${index}]`, id));

  fetch(url, { method: 'POST', body }).catch((err) => {
    console.error('Failed to persist new row order:', err);
  });
}

/**
 * Wires up drag-and-drop reordering. Works for both table modes since it
 * reads whatever's in the DOM at drag time, not how it got there.
 * MutationObserver re-binds SortableJS after any Grid.js re-render,
 * including ones we don't get a callback for (client-side sort/page clicks).
 */
function setupOrderable(wrapper, endpoint, extraFields) {
  let sortableInstance = null;
  let boundTbody = null;

  function bindSortable() {
    const tbody = wrapper.querySelector('tbody');
    if (!tbody) return;

    // SortableJS moves the dragged <tr> live during the drag — that's a
    // mutation too. Only rebuild when tbody is a genuinely different node,
    // or we'd destroy() mid-drag (breaks SortableJS's cleanup, cuts the
    // gesture short after one swap).
    if (tbody === boundTbody) return;

    if (sortableInstance) sortableInstance.destroy();
    boundTbody = tbody;

    sortableInstance = Sortable.create(tbody, {
      animation: 150,
      handle: '.gridjs-drag-handle',
      onEnd: () => {
        const orderedIds = Array.from(tbody.querySelectorAll('tr')).map((tr) => {
          if (tr.hasAttribute('data-row-id')) return tr.getAttribute('data-row-id');
          const marker = tr.querySelector('[data-row-id]');
          if (marker) return marker.getAttribute('data-row-id');
          const lastCell = tr.querySelector('td:last-child');
          return extractRecordId(lastCell ? lastCell.innerHTML : '');
        });
        persistReorder(endpoint, orderedIds, extraFields);
      },
    });
  }

  const observer = new MutationObserver(() => bindSortable());
  observer.observe(wrapper, { childList: true, subtree: true });
  bindSortable();
}

/** Prepends a drag-handle column to an already-rendered table, before Grid.js reads it via `from:`. */
function addHandleColumnToTable(table) {
  const headerRow = table.querySelector('thead tr');
  if (headerRow) {
    const th = document.createElement('th');
    // Empty <th> text -> Grid.js can't derive a valid column id from `from:`.
    th.textContent = '\u2195';
    headerRow.insertBefore(th, headerRow.firstChild);
  }

  table.querySelectorAll('tbody tr').forEach((tr) => {
    const td = document.createElement('td');
    td.innerHTML = '<span class="gridjs-drag-handle" style="cursor:grab">&#8942;&#8942;</span>';
    tr.insertBefore(td, tr.firstChild);
  });
}

/**
 * ---------------------------------------------------------------------
 * 1) CLIENT-SIDE TABLES  ->  <table data-table> (no data-table-async)
 * ---------------------------------------------------------------------
 */
function initClientTable(originalTable) {
  const crudId = originalTable.getAttribute('data-crud-id') || '';
  const orderable = originalTable.hasAttribute('data-order-record');

  const headLabels = Array.from(originalTable.querySelectorAll('thead th'))
    .map((th) => th.textContent.trim());
  const idColumnIndex = findIdColumnIndex(headLabels);

  if (orderable) addHandleColumnToTable(originalTable);

  // Grid.js's `search: true` renders its OWN native `.gridjs-head` search
  // box — different markup/classes than our custom one, and a second
  // header row alongside `.gridjs-header`. Instead of fighting that UI,
  // we disable it entirely, read the rows into memory ourselves, and
  // filter them with our own search input — same approach the async
  // table already uses for server-side filtering.
  const allRows = Array.from(originalTable.querySelectorAll('tbody tr')).map((tr) => {
    const cells = Array.from(tr.children);
    return {
      text: cells.map((td) => td.textContent.trim().toLowerCase()),
      display: cells.map((td) => html(td.innerHTML)),
    };
  });

  let searchKeyword = '';
  function getFilteredRows() {
    const base = searchKeyword
      ? allRows.filter((row) => row.text.some((cell) => cell.includes(searchKeyword)))
      : allRows;
    return base.map((row) => (orderable
      ? [html('<span class="gridjs-drag-handle" style="cursor:grab">&#8942;&#8942;</span>'), ...row.display]
      : row.display));
  }

  const wrapper = document.createElement('div');
  originalTable.insertAdjacentElement('afterend', wrapper);

  const grid = new Grid({
    columns: orderable ? [{ name: '\u2195', sort: false, width: '32px' }, ...headLabels] : headLabels,
    data: () => getFilteredRows(),
    sort: true,
    search: false,
    pagination: { limit: DEFAULT_PAGE_LIMIT },
    language: ptBR,
  }).render(wrapper);

  originalTable.style.display = 'none';

  watchAndBootstrapifyPagination(wrapper);
  watchAndApplyRowIds(wrapper, () => idColumnIndex, () => (orderable ? 1 : 0));
  watchAndWrapThSortContent(wrapper);
  watchAndWrapTableElement(wrapper);

  const header = createGridHeader();
  attachGridHeader(wrapper, header);

  createLengthSelector(header, DEFAULT_PAGE_LIMIT, (newLimit) => {
    grid.updateConfig({ pagination: { limit: newLimit } }).forceRender();
  });

  createSearchInput(header, (newKeyword) => {
    searchKeyword = newKeyword.toLowerCase();
    grid.updateConfig({}).forceRender();
  });

  if (orderable) {
    const orderEndpoint = originalTable.getAttribute('data-order-endpoint') || 'order-record';
    setupOrderable(wrapper, orderEndpoint, { crud_id: crudId });
  }
}

/**
 * ---------------------------------------------------------------------
 * 2) ASYNC/SERVER-SIDE TABLES  ->  <table data-table-async data-crud-id>
 * ---------------------------------------------------------------------
 */
function initAsyncTable(originalTable, singleTableMode = false) {
  const listingType = originalTable.getAttribute('data-listing-type');
  const listingKey = originalTable.getAttribute('data-listing-key');
  const isCustomListing = listingType !== null && listingKey !== null;
  const listingParams = originalTable.getAttribute('data-listing-params');
  const listUrl = isCustomListing ? REST_API_CUSTOM_LISTING_URL : REST_API_LIST_URL;
  const orderable = originalTable.hasAttribute('data-order-record');

  // The loader div is a SIBLING of the table (inside .crud-body), not an ancestor.
  const loader = originalTable.parentElement
    ? originalTable.parentElement.querySelector('[data-table-loader]')
    : null;

  const headLabels = Array.from(originalTable.querySelectorAll('thead th'))
    .map((th) => th.textContent.trim());

  const columns = orderable
    ? [{ name: '\u2195', sort: false, width: '32px' }, ...headLabels]
    : headLabels;

  const wrapper = document.createElement('div');
  originalTable.insertAdjacentElement('afterend', wrapper);

  // Marker + refresh hook on the STABLE parent container (never touched by
  // Grid.js/Preact — `wrapper` is, and its own attributes aren't a safe
  // place to rely on) so libs.js's delete/duplicate handler can find and
  // soft-refresh this table via `.closest()`. refreshGridTable is assigned
  // near the end of this function, once `grid` exists.
  const refreshableRoot = originalTable.parentElement;
  if (refreshableRoot) refreshableRoot.classList.add('gridjs-refreshable');

  let draw = 0;
  let sortState = [];
  let searchKeyword = singleTableMode ? getUrlSearch() : '';
  let pageState = {
    page: singleTableMode ? getUrlPage() - 1 : 0,
    limit: DEFAULT_PAGE_LIMIT,
  };
  let idColumnIndex = -1;
  let pageOutOfRange = false;
  let hasLoadedOnce = false;
  let lastTotal = 0;
  let isLoading = true;
  let suppressNextLoadingFlicker = false;
  let isSearchTriggeredFetch = false; // skips the full loader/container hide — see createSearchInput() below
  let searchInputEl = null; // set once createSearchInput() runs below; used to restore focus after a search fetch
  let currentRequest = null;
  // Set right before any of OUR OWN programmatic pagination changes
  // (initial construction, length change, search reset, refreshGridTable)
  // — Grid.js's own internal page counter only updates correctly from a
  // REAL click (real or our simulated one for the first-load fix); every
  // other trigger of updateConfig()/forceRender() gets the page it had
  // BEFORE our change reported back through this hook, silently resetting
  // pageState. Setting this tells the hook what we actually want instead
  // of trusting Grid.js's report. null = trust Grid.js (genuine click).
  let expectedNextPage = null;

  function buildPaginationConfig(limit, page = pageState.page) {
    return {
      limit,
      page,
      server: {
        url: (prev, page, lim) => {
          const resolvedPage = expectedNextPage !== null ? expectedNextPage : page;
          expectedNextPage = null;
          pageState = { page: resolvedPage, limit: lim };
          if (singleTableMode && hasLoadedOnce) syncUrlPage(resolvedPage + 1);
          return prev;
        },
      },
    };
  }

  expectedNextPage = pageState.page; // initial construction — see the flag's docblock above

  const grid = new Grid({
    columns,

    sort: {
      multiColumn: false,
      server: {
        url: (prev, columns) => {
          sortState = columns;
          return prev;
        },
      },
    },

    // Custom search input below replaces Grid.js's built-in search entirely.
    search: false,
    pagination: buildPaginationConfig(pageState.limit),
    language: ptBR,
    server: {
      url: listUrl,
      method: 'POST',
      data: () => {
        draw += 1;
        const isThisSearchFetch = isSearchTriggeredFetch;
        isSearchTriggeredFetch = false;

        if (isThisSearchFetch) {
          showSearchLoadingOverlay(wrapper);
        } else if (suppressNextLoadingFlicker) {
          suppressNextLoadingFlicker = false;
        } else {
          isLoading = true;
          setLoaderVisible(loader, true);
        }

        if (currentRequest) currentRequest.abort();
        const controller = new AbortController();
        currentRequest = controller;

        const dtRequest = {
          draw,
          start: pageState.page * pageState.limit,
          length: pageState.limit,
          search: { value: searchKeyword || '', regex: false },
          order: sortState.length
            ? [{
                column: sortState[0].index - (orderable ? 1 : 0),
                dir: sortState[0].direction === 1 ? 'asc' : 'desc',
              }]
            : [],
          columns: headLabels.map((label, index) => ({
            data: index,
            name: label,
            searchable: true,
            orderable: true,
            search: { value: '', regex: false },
          })),
        };

        const body = new FormData();
        appendFormData(body, dtRequest, '');
        if (isCustomListing) {
          body.append('listing_type', listingType);
          body.append('listing_key', listingKey);
          if (listingParams) body.append('listing_params', listingParams);
        } else {
          const crudId = originalTable.getAttribute('data-crud-id') || '';
          if (crudId) body.append('crud_id', crudId);
        }

        return fetch(listUrl, { method: 'POST', body, signal: controller.signal })
          .then((res) => res.json())
          .then((json) => {
            const wasFirstLoad = !hasLoadedOnce;
            hasLoadedOnce = true;

            if (idColumnIndex === -1 && Array.isArray(json.head)) {
              idColumnIndex = findIdColumnIndex(json.head);
            }

            const recordsFiltered = json.recordsFiltered || 0;
            lastTotal = recordsFiltered;

            if (singleTableMode) {
              const maxPage = Math.max(1, Math.ceil(recordsFiltered / pageState.limit));
              pageOutOfRange = (pageState.page + 1) > maxPage;
            } else {
              pageOutOfRange = false;
            }

            // Grid.js's internal page counter doesn't follow our forced
            // initial page — simulating a real click on the correct
            // button is the only way to sync its internal state, so
            // Previous/Next/page clicks behave normally afterward.
            if (wasFirstLoad && singleTableMode && pageState.page > 0 && !pageOutOfRange) {
              const targetPage = pageState.page + 1;
              requestAnimationFrame(() => requestAnimationFrame(() => {
                const pagesContainer = wrapper.querySelector('.gridjs-pages');
                if (!pagesContainer) return;
                const targetButton = Array.from(pagesContainer.querySelectorAll('button')).find(
                  (btn) => btn.textContent.trim() === String(targetPage)
                );
                if (targetButton) {
                  suppressNextLoadingFlicker = true;
                  targetButton.click();
                }
              }));
            }

            const rows = (json.data || []).map((row) => {
              const cells = row.map((cell) => html(cell == null ? '-' : String(cell)));
              return orderable
                ? [html('<span class="gridjs-drag-handle" style="cursor:grab">&#8942;&#8942;</span>'), ...cells]
                : cells;
            });

            if (pageOutOfRange) {
              const colspan = orderable ? headLabels.length + 1 : headLabels.length;
              // No native colspan support in Grid.js's cell model — overwrite the tbody directly.
              requestAnimationFrame(() => requestAnimationFrame(() => {
                const tbody = wrapper.querySelector('tbody');
                if (tbody) {
                  tbody.innerHTML = `<tr><td colspan="${colspan}">Esta página da tabela não existe</td></tr>`;
                }
              }));
            }

            return { data: rows, total: recordsFiltered };
          })
          .catch((err) => {
            if (err.name === 'AbortError') {
              // Superseded by a newer request — never resolve, so this stale response never renders.
              return new Promise(() => {});
            }
            console.error('Grid.js ajax error:', err);
            return { data: [], total: 0 };
          })
          .finally(() => {
            if (currentRequest === controller) {
              currentRequest = null;
              isLoading = false;
              requestAnimationFrame(() => requestAnimationFrame(() => {
                setLoaderVisible(loader, false);
                if (isThisSearchFetch) {
                  hideSearchLoadingOverlay(wrapper);
                  if (searchInputEl && document.activeElement !== searchInputEl) {
                    const cursorPos = searchInputEl.value.length;
                    searchInputEl.focus();
                    searchInputEl.setSelectionRange(cursorPos, cursorPos);
                  }
                }
              }));
            }
          });
      },
    },
  });

  grid.render(wrapper);
  originalTable.style.display = 'none';

  watchAndSyncContainerVisibility(wrapper, () => isLoading);
  watchAndBootstrapifyPagination(wrapper, () => ({
    page: pageState.page,
    limit: pageState.limit,
    total: lastTotal,
  }));
  watchAndApplyRowIds(wrapper, () => idColumnIndex, () => (orderable ? 1 : 0));
  watchAndWrapThSortContent(wrapper);
  watchAndWrapTableElement(wrapper);

  // Refetches the current page/search/sort as-is (no reset) — same
  // "recreate the config object to force a refetch" trick used by the
  // length selector and search input below.
  if (refreshableRoot) {
    refreshableRoot.refreshGridTable = () => {
      expectedNextPage = pageState.page;
      grid.updateConfig({ pagination: buildPaginationConfig(pageState.limit) }).forceRender();
    };
  }

  const header = createGridHeader();
  attachGridHeader(wrapper, header);

  createLengthSelector(header, pageState.limit, (newLimit) => {
    expectedNextPage = pageState.page;
    grid.updateConfig({ pagination: buildPaginationConfig(newLimit) }).forceRender();
  });

  searchInputEl = createSearchInput(header, (newKeyword) => {
    searchKeyword = newKeyword;
    if (singleTableMode) syncUrlSearch(newKeyword);
    // New search can have far fewer pages than the current one — reset to page 0.
    pageState = { ...pageState, page: 0 };
    expectedNextPage = 0;
    if (singleTableMode) syncUrlPage(1);
    isSearchTriggeredFetch = true;
    grid.updateConfig({ pagination: buildPaginationConfig(pageState.limit) }).forceRender();
  }, searchKeyword);

  if (orderable) {
    const orderEndpoint = originalTable.getAttribute('data-order-endpoint') || 'order-record';
    const extraFields = isCustomListing
      ? { listing_type: listingType, listing_key: listingKey }
      : { crud_id: originalTable.getAttribute('data-crud-id') || '' };
    setupOrderable(wrapper, orderEndpoint, extraFields);
  }
}

/**
 * ---------------------------------------------------------------------
 * Bootstrap
 * ---------------------------------------------------------------------
 */
document.addEventListener('DOMContentLoaded', () => {
  const asyncTables = document.querySelectorAll('[data-table-async]');
  const singleTableMode = asyncTables.length === 1;

  asyncTables.forEach((table) => initAsyncTable(table, singleTableMode));

  document
    .querySelectorAll('.data-table:not([data-table-async]), [data-table]:not([data-table-async])')
    .forEach(initClientTable);
});
